using System;using System.Linq;using UnityEngine;using UnityEngine.UI;using UnityEditor;
public static class FixGuideHeadings {
 public static string Run(){int count=0;foreach(var entry in BlueprintGuide.Entries){foreach(bool english in new[]{false,true}){var title=entry.HeadingFor(english);var alias=entry.Alias;if(alias!=null&&alias.Symbol.Length>0&&System.Text.RegularExpressions.Regex.Matches(title,@"(?<![0-9])"+System.Text.RegularExpressions.Regex.Escape(alias.Symbol)+@"(?![0-9])").Count>1)throw new Exception("Duplicate heading: "+title);count++;}}
 var root=PrefabUtility.LoadPrefabContents("Assets/UI/ForgeGameUI.prefab");try{foreach(var action in root.GetComponentsInChildren<ForgeUIAction>(true)){if(!action.action.StartsWith("guide-entry:"))continue;int index=int.Parse(action.action.Substring(12));action.button.GetComponentInChildren<Text>(true).text=BlueprintGuide.Entries[index].HeadingFor(false);}PrefabUtility.SaveAsPrefabAsset(root,"Assets/UI/ForgeGameUI.prefab");}finally{PrefabUtility.UnloadPrefabContents(root);}AssetDatabase.SaveAssets();return "PASS "+count+" numeric/English headings; prefab labels updated.\n"+string.Join("\n",BlueprintGuide.Entries.Where(e=>e.Id=="extension-5"||e.Alias?.Symbol=="400"||e.Section=="대장장이와 다이아몬드").Select(e=>e.HeadingFor(false)));}
}
